//! Replays golden vectors generated by the TypeScript rules (npm run vectors) and checks the Rust
//! payoff maths gives byte-identical results.
use pinky_contract::payoff::*;

fn num(v: &serde_json::Value) -> u128 {
    v.as_str().unwrap().parse::<u128>().unwrap()
}
fn int(v: &serde_json::Value) -> i128 {
    v.as_str().unwrap().parse::<i128>().unwrap()
}
fn mv(v: &serde_json::Value) -> Move {
    match v.as_str().unwrap() {
        "KEEP" => Move::Keep,
        "BREAK" => Move::Break,
        other => panic!("bad move {other}"),
    }
}

#[test]
fn rust_matches_typescript_on_every_vector() {
    let raw = include_str!("vectors.json");
    let rows: Vec<serde_json::Value> = serde_json::from_str(raw).unwrap();
    assert!(rows.len() >= 2000, "vector file looks truncated: {}", rows.len());
    let (mut settle_n, mut ct_n, mut pt_n) = (0, 0, 0);
    for row in &rows {
        let pr = row["params"].as_array().unwrap();
        let p = Params { rake_bps: num(&pr[0]), y_max_bps: num(&pr[1]), drip: num(&pr[2]), forfeit_bps: num(&pr[3]) };
        validate(&p);
        let stake = num(&row["stake"]);
        let out = row["out"].as_array().unwrap();
        let want = Settlement { player: num(&out[0]), character: num(&out[1]), jar_delta: int(&out[2]), house: num(&out[3]) };
        let got = match row["kind"].as_str().unwrap() {
            "settle" => {
                settle_n += 1;
                let jar = num(&row["jar"]);
                assert_eq!(bonus(stake, jar, &p), num(&row["bonus"]), "bonus mismatch {row}");
                settle(stake, mv(&row["player"]), mv(&row["character"]), jar, &p)
            }
            "char_timeout" => {
                ct_n += 1;
                settle_character_timeout(stake)
            }
            "player_timeout" => {
                pt_n += 1;
                settle_player_timeout(stake, &p)
            }
            k => panic!("unknown kind {k}"),
        };
        assert_eq!(got, want, "payoff mismatch for {row}");
        assert_eq!(got.total(), 2 * stake as i128, "conservation broken for {row}");
    }
    assert!(settle_n > 1500 && ct_n > 300 && pt_n > 300, "{settle_n} {ct_n} {pt_n}");
}

#[test]
fn planted_control_a_wrong_rule_fails_the_vectors() {
    // If the rake were off by one basis point the golden vectors must disagree.
    let raw = include_str!("vectors.json");
    let rows: Vec<serde_json::Value> = serde_json::from_str(raw).unwrap();
    let mut disagreements = 0;
    for row in rows.iter().filter(|r| r["kind"] == "settle") {
        let pr = row["params"].as_array().unwrap();
        let p = Params { rake_bps: num(&pr[0]) + 1, y_max_bps: num(&pr[1]), drip: num(&pr[2]), forfeit_bps: num(&pr[3]) };
        let out = row["out"].as_array().unwrap();
        let want = Settlement { player: num(&out[0]), character: num(&out[1]), jar_delta: int(&out[2]), house: num(&out[3]) };
        if settle(num(&row["stake"]), mv(&row["player"]), mv(&row["character"]), num(&row["jar"]), &p) != want {
            disagreements += 1;
        }
    }
    assert!(disagreements > 100, "the vectors cannot tell a wrong rake from the right one: {disagreements}");
}
